const workflowName = 'wf_instagram_simple_post_publish';
const startedMs = Date.now();
const checkedAt = new Date().toISOString();
const env = typeof $env === 'object' && $env ? $env : {};
const graphApiVersion = String(env.GRAPH_API_VERSION || 'v25.0').trim();
const rootAccessToken = String(env.INSTAGRAM_GRAPH_API_TOKEN || '').trim();
const publishEnabled = String(env.INSTAGRAM_PUBLISH_ENABLED || 'false').trim().toLowerCase() === 'true';
const preferredPageId = String(env.INSTAGRAM_TARGET_PAGE_ID || '').trim();
