    height: Number($json.height ?? 0) || null
  }
};
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const looksLikePublicUrl = /^https?:\/\//i.test(assetUrl);
const looksLikeJpegUrl = /\.jpe?g(?:[?#].*)?$/i.test(assetUrl);
const allowedStatuses = new Set(['assets_ready', 'qa_approved']);
const composedCaption = [captionFinal, hashtagsFinal].filter(Boolean).join('\n\n').trim();
const altText = title ? `${title} Instagram post image` : 'Instagram post image';
if (!uuidPattern.test(contentId)) {
  errors.push('Fetch Next Instagram Publish Item did not produce a valid content_id.');
}
if (!title) {
  errors.push('Fetch Next Instagram Publish Item did not produce a title.');
}
if (!allowedStatuses.has(contentStatus)) {
  errors.push(`Content status must be assets_ready or qa_approved before publish. Received: ${contentStatus || '<empty>'}.`);
}
if (!captionFinal) {
  errors.push('caption_final is empty. Run wf_caption_and_hashtags before publishing.');
}
if (!assetUrl) {
  errors.push('storage_url is empty. Run wf_simple_post_image_asset before publishing.');
} else {
  if (!looksLikePublicUrl) {
    errors.push('storage_url must be a public http(s) URL so Meta can fetch the image.');
  }
  if (!(assetMimeType === 'image/jpeg' || assetMimeType === 'image/jpg' || looksLikeJpegUrl)) {
    errors.push('The publish asset must be a JPEG image. Set MVP_SIMPLE_POST_IMAGE_URL to a public .jpg or .jpeg URL and rerun wf_simple_post_image_asset.');
  }
}
if (!publishEnabled) {
  errors.push('INSTAGRAM_PUBLISH_ENABLED is not true in the running n8n container env. Set it in the repo-root .env and recreate n8n before attempting a live publish.');
}
if (!rootAccessToken) {
  errors.push('INSTAGRAM_GRAPH_API_TOKEN is empty in the running n8n container env.');
}
const buildResult = (overrides = {}) => [{
  json: {
    workflow_name: workflowName,
    content_id: contentId,
    title,
    caption_final: captionFinal,
    hashtags_final: hashtagsFinal,
    content_status_before_run: contentStatus,
    publish_status_before_run: publishStatus,
    run_status: overrides.run_status ?? (errors.length ? 'failed' : 'success'),
    publish_status_after_run: overrides.publish_status_after_run ?? (errors.length ? 'failed' : 'published'),
    error_message: overrides.error_message ?? errors.join(' | '),
    instagram_media_id: overrides.instagram_media_id ?? '',
    instagram_container_id: overrides.instagram_container_id ?? '',
