    }
  }
}];
if (errors.length) {
  details.validation_errors = [...errors];
  return buildResult();
}
const graphRequest = async ({ method = 'GET', path, token, qs, body }) => {
  const options = {
    method,
    url: `https://graph.facebook.com/${graphApiVersion}/${path}`,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    headers: {
      Authorization: `Bearer ${token}`
    }
  };
  if (qs) {
    options.qs = qs;
  }
  if (body) {
    options.headers['Content-Type'] = 'application/json';
    options.body = body;
  }
  try {
    const response = await helpers.httpRequest(options);
    const statusCode = Number(response.statusCode ?? 0);
    const responseBody = response.body ?? {};
    return {
      ok: statusCode >= 200 && statusCode < 300 && !responseBody.error,
      status: statusCode,
      body: responseBody
    };
  } catch (error) {
    return {
      ok: false,
      status: Number(error?.statusCode ?? 0),
      body: error?.response?.body ?? {
        error: {
          message: error.message
        }
      }
    };
  }
};
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
try {
  const pagesResponse = await graphRequest({
    path: 'me/accounts',
    token: rootAccessToken,
    qs: {
      fields: 'id,name'
    }
  });
  details.page_lookup = {
    http_status: pagesResponse.status,
    page_count: Array.isArray(pagesResponse.body?.data) ? pagesResponse.body.data.length : 0
  };
  if (!pagesResponse.ok) {
    return buildResult({
      run_status: 'failed',
      publish_status_after_run: 'failed',
      error_message: `/me/accounts failed: ${pagesResponse.body?.error?.message ?? 'unknown error'}`,
      details_json: {
        ...details,
        page_lookup: {
          ...details.page_lookup,
          body: pagesResponse.body
        }
      }
    });
  }
  const pages = Array.isArray(pagesResponse.body?.data) ? pagesResponse.body.data : [];
  const selectedPage = preferredPageId
    ? pages.find((page) => String(page.id) === preferredPageId)
    : pages[0];
  if (!selectedPage) {
    return buildResult({
      run_status: 'failed',
      publish_status_after_run: 'failed',
      error_message: preferredPageId
        ? `INSTAGRAM_TARGET_PAGE_ID=${preferredPageId} was not returned by /me/accounts.`
        : 'No linked Facebook Pages were returned by /me/accounts.',
      details_json: {
        ...details,
        linked_pages: pages
      }
    });
  }
  details.selected_page = {
    id: selectedPage.id,
    name: selectedPage.name
  };
  const pageDetailsResponse = await graphRequest({
    path: String(selectedPage.id),
    token: rootAccessToken,
    qs: {
      fields: 'id,name,access_token,instagram_business_account{id,username},connected_instagram_account{id,username}'
    }
  });
  details.page_details_lookup = {
    http_status: pageDetailsResponse.status
  };
  if (!pageDetailsResponse.ok) {
    return buildResult({
      run_status: 'failed',
      publish_status_after_run: 'failed',
      error_message: `Page metadata lookup failed: ${pageDetailsResponse.body?.error?.message ?? 'unknown error'}`,
      details_json: {
        ...details,
        page_details_lookup: {
          ...details.page_details_lookup,
          body: pageDetailsResponse.body
        }
      }
    });
  }
  const pageDetails = pageDetailsResponse.body ?? {};
  const discoveredIgAccount = pageDetails.instagram_business_account ?? pageDetails.connected_instagram_account ?? null;
  const selectedIgAccount = preferredIgUserId
    ? discoveredIgAccount && String(discoveredIgAccount.id) === preferredIgUserId
      ? discoveredIgAccount
      : null
    : discoveredIgAccount;
  if (!selectedIgAccount) {
    return buildResult({
      run_status: 'failed',
      publish_status_after_run: 'failed',
      error_message: preferredIgUserId
        ? `INSTAGRAM_IG_USER_ID=${preferredIgUserId} was not returned for the selected Page.`
        : 'No Instagram professional account was returned for the selected Page.',
      details_json: {
        ...details,
        page_details_lookup: {
          ...details.page_details_lookup,
          body: {
            id: pageDetails.id,
            name: pageDetails.name,
            instagram_business_account: pageDetails.instagram_business_account ?? null,
            connected_instagram_account: pageDetails.connected_instagram_account ?? null
          }
        }
      }
    });
  }
  const pageAccessToken = String(pageDetails.access_token ?? '').trim() || rootAccessToken;
  details.instagram_account = {
    id: selectedIgAccount.id,
    username: selectedIgAccount.username ?? null
  };
  const limitResponse = await graphRequest({
    path: `${selectedIgAccount.id}/content_publishing_limit`,
    token: pageAccessToken
  });
  details.content_publishing_limit = {
    http_status: limitResponse.status,
    quota_usage: Number(limitResponse.body?.data?.[0]?.quota_usage ?? 0)
  };
  if (!limitResponse.ok) {
    return buildResult({
      run_status: 'failed',
      publish_status_after_run: 'failed',
      error_message: `content_publishing_limit failed: ${limitResponse.body?.error?.message ?? 'unknown error'}`,
      details_json: {
        ...details,
