      caption: composedCaption,
      alt_text: altText
    }
  });
  details.container_create = {
    http_status: containerResponse.status,
    body: containerResponse.body
  };
  if (!containerResponse.ok || !containerResponse.body?.id) {
    return buildResult({
      run_status: 'failed',
      publish_status_after_run: 'failed',
