    });
    const statusCode = String(statusResponse.body?.status_code ?? '').toUpperCase();
    statusChecks.push({
      attempt,
      http_status: statusResponse.status,
      status_code: statusCode || null,
      body: statusResponse.body
    });
    if (!statusResponse.ok) {
      return buildResult({
        run_status: 'failed',
        publish_status_after_run: 'failed',
        instagram_container_id: containerId,
        error_message: `Container status polling failed: ${statusResponse.body?.error?.message ?? 'unknown error'}`,
        details_json: {
          ...details,
          container_status_checks: statusChecks
        }
      });
    }
    finalContainerStatus = statusCode;
    if (statusCode === 'FINISHED') {
      break;
    }
    if (statusCode === 'ERROR' || statusCode === 'EXPIRED') {
      break;
    }
    await sleep(2000);
  }
  details.container_status_checks = statusChecks;
  if (finalContainerStatus !== 'FINISHED') {
    return buildResult({
      run_status: 'failed',
      publish_status_after_run: 'failed',
      instagram_container_id: containerId,
      error_message: `Container ${containerId} did not reach FINISHED status. Last status: ${finalContainerStatus || 'unknown'}.`,
      details_json: details
    });
  }
