    method: 'POST',
    path: `${selectedIgAccount.id}/media_publish`,
    token: pageAccessToken,
    body: {
      creation_id: containerId
    }
  });
  details.publish_response = {
    http_status: publishResponse.status,
    body: publishResponse.body
  };
  if (!publishResponse.ok || !publishResponse.body?.id) {
    return buildResult({
      run_status: 'failed',
      publish_status_after_run: 'failed',
      instagram_container_id: containerId,
      error_message: `media_publish failed: ${publishResponse.body?.error?.message ?? 'unknown error'}`,
      details_json: details
    });
  }
  return buildResult({
    run_status: 'success',
    publish_status_after_run: 'published',
    instagram_container_id: containerId,
    instagram_media_id: String(publishResponse.body.id),
    error_message: '',
    details_json: details
  });
